@namespace sv_252f047c2d674da8b0f5db12fdf6a618.Components.Pages.Settings
@using sv_252f047c2d674da8b0f5db12fdf6a618.Services

<div class="settings-section">
    <h2>Appearance Settings</h2>

    @if (_settings is null)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="appearance-form">
            <!-- Theme Selector -->
            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            @theme
                        </label>
                    }
                </div>
            </div>

            <!-- Font Size Selector -->
            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            @size
                        </label>
                    }
                </div>
            </div>

            <!-- Language Dropdown -->
            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_language" class="form-control">
                    <option value="en">English</option>
                    <option value="es">Spanish</option>
                    <option value="fr">French</option>
                    <option value="de">German</option>
                    <option value="ja">Japanese</option>
                    <option value="zh">Chinese</option>
                </select>
            </div>

            <!-- Compact Mode Toggle -->
            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_compactMode" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    Compact Mode
                </label>
            </div>

            <!-- Live Preview -->
            <div class="preview-area @GetPreviewClasses()">
                <h4>Live Preview</h4>
                <p class="preview-text">This is how your content will look with the selected settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>Theme: @_theme | Font: @_fontSize | Compact: @(_compactMode ? "Yes" : "No")</p>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="Save">Save</button>
            </div>

            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="toast-message toast-success">@_message</div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private AppearanceSettings? _settings;
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private string _message = "";

    protected override void OnParametersSet()
    {
        if (Settings is not null && _settings != Settings)
        {
            _settings = Settings;
            _theme = _settings.Theme;
            _fontSize = _settings.FontSize;
            _language = _settings.Language;
            _compactMode = _settings.CompactMode;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_theme.ToLowerInvariant()} preview-font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " preview-compact";
        return classes;
    }

    private async Task Save()
    {
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
        _settings = updated;
        _message = "Appearance saved!";
        StateHasChanged();
        _ = ClearMessage();
    }

    private async Task ClearMessage()
    {
        await Task.Delay(3000);
        _message = "";
        StateHasChanged();
    }
}

