{"file_text": ".settings-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: var(--bs-gray-100, #f8f9fa);
    border-right: 1px solid var(--bs-gray-300, #dee2e6);
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    transition: all 0.2s ease;
    border-left: 3px solid transparent;
    color: var(--bs-gray-700, #495057);
}

.settings-nav-item:hover {
    background: var(--bs-gray-200, #e9ecef);
}

.settings-nav-item.active {
    background: var(--bs-primary-bg-subtle, #e7f1ff);
    border-left-color: var(--bs-primary, #0d6efd);
    color: var(--bs-primary, #0d6efd);
    font-weight: 600;
}

.nav-icon {
    font-size: 1.2rem;
}

/* Main content */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
}

/* Forms */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
    color: var(--bs-gray-700, #495057);
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--bs-gray-300, #dee2e6);
    border-radius: 0.375rem;
    font-size: 1rem;
    transition: border-color 0.15s ease;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: var(--bs-primary, #0d6efd);
    box-shadow: 0 0 0 0.2rem rgba(13, 110, 253, 0.15);
}

textarea.form-control {
    resize: vertical;
}

/* Buttons */
.btn {
    padding: 0.5rem 1rem;
    border: none;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.15s ease;
}

.btn-primary {
    background: var(--bs-primary, #0d6efd);
    color: white;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-secondary {
    background: var(--bs-gray-200, #e9ecef);
    color: var(--bs-gray-700, #495057);
}

.btn-secondary:hover {
    background: var(--bs-gray-300, #dee2e6);
}

.btn-danger {
    background: var(--bs-danger, #dc3545);
    color: white;
}

.btn-danger:hover {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.25rem 0.5rem;
    font-size: 0.8rem;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Toast / Messages */
.toast-message {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    animation: fadeIn 0.3s ease;
}

.toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-info {
    background: #cff4fc;
    color: #055160;
    border: 1px solid #b6effb;
}

.toast-error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-0.5rem); }
    to { opacity: 1; transform: translateY(0); }
}

/* Avatar */
.avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

.avatar-image {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid var(--bs-gray-300, #dee2e6);
    margin-bottom: 0.5rem;
}

.avatar-url {
    font-size: 0.8rem;
    color: var(--bs-gray-500, #adb5bd);
    word-break: break-all;
}

/* Toggle switches */
.toggle-group {
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-weight: 400;
}

.toggle-input {
    width: 2.5rem;
    height: 1.25rem;
    appearance: none;
    background: var(--bs-gray-400, #ced4da);
    border-radius: 1rem;
    position: relative;
    cursor: pointer;
    transition: background 0.2s ease;
    flex-shrink: 0;
}

.toggle-input::after {
    content: '';
    position: absolute;
    width: 1rem;
    height: 1rem;
    background: white;
    border-radius: 50%;
    top: 0.125rem;
    left: 0.125rem;
    transition: transform 0.2s ease;
}

.toggle-input:checked {
    background: var(--bs-primary, #0d6efd);
}

.toggle-input:checked::after {
    transform: translateX(1.25rem);
}

